select * from INFORMATION_SCHEMA.CLUSTER_CONFIG d where length(d.value)>0 and d.key in ('advertise-address','host','log.file.filename','log.enable-slow-log','log.record-plan-in-slow-log','log.slow-query-file','log.slow-threshold','lower-case-table-names','path','store','advertise-client-urls','advertise-peer-urls','client-urls','cluster-version','data-dir','initial-cluster','lease','pd-server.dashboard-address','peer-urls','log-file','log-format','log-level','pd.endpoints','raft-engine.dir','raft-engine.enable','oom-action')